mapper.select:
SELECT c.id, c.tenant_id, c.name,
       c.`key` AS config_key, c.`value` AS config_value,
       c.type, c.status, c.is_builtin, c.remark, c.version,
       c.create_by, c.create_time, c.update_by, c.update_time
FROM sys_config c
WHERE c.is_deleted = 0
AND c.tenant_id = #{tenantId}

    AND (c.name LIKE CONCAT('%', #{request.keyword}, '%')
         OR c.`key` LIKE CONCAT('%', #{request.keyword}, '%'))


    AND c.type = #{request.type}


    AND c.status = #{request.status}



        ORDER BY ${request.safeSortField()} ${request.safeSortOrder()}


        ORDER BY c.create_time DESC
